CREATE TABLE payment_intents (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, order_id VARCHAR(64) NOT NULL, provider VARCHAR(16) NOT NULL, provider_payment_id VARCHAR(160), status VARCHAR(32) NOT NULL, amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), currency CHAR(3) NOT NULL, client_secret VARCHAR(500), idempotency_key VARCHAR(160) NOT NULL, request_hash CHAR(64) NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE (user_id, idempotency_key), UNIQUE (provider, provider_payment_id));
CREATE INDEX payment_intents_order_idx ON payment_intents(order_id);
CREATE INDEX payment_intents_reconcile_idx ON payment_intents(status, updated_at);
CREATE TABLE payment_attempts (id VARCHAR(64) PRIMARY KEY, payment_id VARCHAR(64) NOT NULL REFERENCES payment_intents(id), attempt_no INTEGER NOT NULL, status VARCHAR(32) NOT NULL, provider_payment_id VARCHAR(160), error_code VARCHAR(100), error_message VARCHAR(500), created_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, UNIQUE (payment_id, attempt_no));
CREATE TABLE payment_transactions (id VARCHAR(64) PRIMARY KEY, payment_id VARCHAR(64) NOT NULL REFERENCES payment_intents(id), type VARCHAR(32) NOT NULL, provider_transaction_id VARCHAR(160), amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), currency CHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, idempotency_key VARCHAR(160), created_at TIMESTAMPTZ NOT NULL, UNIQUE (payment_id, type, idempotency_key));
CREATE TABLE payment_webhooks (id VARCHAR(64) PRIMARY KEY, provider VARCHAR(16) NOT NULL, provider_event_id VARCHAR(200) NOT NULL, payload_json JSONB NOT NULL, received_at TIMESTAMPTZ NOT NULL, processed_at TIMESTAMPTZ, UNIQUE (provider, provider_event_id));
CREATE TABLE payment_reconciliation_runs (id VARCHAR(64) PRIMARY KEY, payment_id VARCHAR(64) NOT NULL REFERENCES payment_intents(id), provider_status VARCHAR(32) NOT NULL, outcome VARCHAR(32) NOT NULL, checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE payment_inbox_events (event_id VARCHAR(160) PRIMARY KEY, received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE payment_outbox_events (id VARCHAR(64) PRIMARY KEY, aggregate_id VARCHAR(64) NOT NULL, event_type VARCHAR(100) NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, occurred_at TIMESTAMPTZ NOT NULL, correlation_id VARCHAR(160) NOT NULL, payload_json JSONB NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX payment_outbox_unpublished_idx ON payment_outbox_events(published_at, occurred_at) WHERE published_at IS NULL;
